import com.pocketstock.app.Csv;import java.util.*;
class CsvTest{static void check(boolean ok){if(!ok)throw new AssertionError();}public static void main(String[] args){var r=Csv.detect("\uFEFFCode;Description;Price\r\n001;\"Juice; 2L\";15,99");check(r.get(1).get(0).equals("001"));check(r.get(1).get(2).equals("15,99"));r=Csv.parse("Name,Notes\r\n\"A \"\"brand\"\"\",\"line 1\nline 2\"",',');check(r.get(1).get(0).equals("A \"brand\""));check(r.get(1).get(1).equals("line 1\nline 2"));var original=Arrays.asList("001","comma, quote\"\nand newline","");check(Csv.parse(Csv.line(original),',').get(0).equals(original));boolean threw=false;try{Csv.parse("Name\n\"unfinished",',');}catch(IllegalArgumentException e){threw=true;}check(threw);check(Csv.detect("Code\tName\n01\tJuice").get(0).size()==2);System.out.println("All Java CSV checks passed.");}}
